INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ce6a8b97-d19b-4c08-aefa-f7c0831308ba', '2bc5414a-4d55-48d1-8f55-1ce12d696c4e', 0, 'Five distinct factor categories — knowledge (something you know, like a password), possession (something you have, like a hardware key), inherence (something you are, like a fingerprint or other biometric), location (somewhere you are, like a verified GPS position or network origin), and behavior (something you do, like typing rhythm or gait) — MFA (covered generally in a prior paper) combines factors from at least two DIFFERENT categories, not simply two different examples from the SAME category (e.g., a password plus a PIN are both knowledge factors, so combining them does not actually constitute true multi-factor authentication).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9801e6c-230a-4c20-8a82-6ed45dfcc1ad', '2bc5414a-4d55-48d1-8f55-1ce12d696c4e', 1, 'Two distinct factor categories, since knowledge, possession, inherence, location, and behavior are all considered the exact same single authentication factor category.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a5e0ae62-cac6-48ef-9411-4e1ab1fa417d', '2bc5414a-4d55-48d1-8f55-1ce12d696c4e', 2, 'A gap analysis, since gap analyses are specifically defined as the five-category taxonomy of authentication factors including knowledge, possession, inherence, location, and behavior.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5e6334bc-45ff-45fe-8aed-d50f31b0058a', '2bc5414a-4d55-48d1-8f55-1ce12d696c4e', 3, 'Authentication factors cannot meaningfully be grouped into any distinct categories; every authentication method is functionally identical regardless of its underlying mechanism.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0e4a0430-0910-4a58-b38a-f05cc9f95fce', '334d4af7-a35f-4794-a1e5-265188b6cec5', 0, 'Due diligence (the reasonable INVESTIGATION performed BEFORE a decision or action — here, thoroughly researching the vendor before signing) and due care (the ongoing, ROUTINE, reasonable maintenance of security practices AFTER a decision has been made — here, continuing to patch, monitor, and review access on an ongoing basis); both terms describe a legally and practically meaningful standard of "reasonable" behavior, but due diligence is specifically about pre-decision investigation, while due care is about ongoing, sustained responsible practice afterward.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c540e26f-9488-46d6-ad32-f8f8316b4f61', '334d4af7-a35f-4794-a1e5-265188b6cec5', 1, 'Due care is specifically the pre-decision investigation performed before signing a contract, while due diligence is the ongoing, routine maintenance of security practices afterward — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7bcc2f71-4ce6-4ac5-b209-fb9aa75bdf82', '334d4af7-a35f-4794-a1e5-265188b6cec5', 2, 'Due diligence and due care are two different names for the exact same concept, with no meaningful distinction in timing or focus between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('20fb3c6b-c99c-4730-a724-ffce96624b47', '334d4af7-a35f-4794-a1e5-265188b6cec5', 3, 'Neither due diligence nor due care carries any real legal or practical significance; these are purely informal terms with no bearing on an organization''s actual responsibility or liability.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9a48dd22-3c56-496b-8ffc-f5a4dbba8ce5', '3dc80833-8e27-452a-83a5-8c56dbb66ee9', 0, 'A virus (requires a host file and typically some user action, like opening an infected attachment or running an infected program, to actually execute and begin spreading — it cannot propagate entirely on its own) and a worm (self-replicating and self-propagating across a network entirely independently, actively scanning for and exploiting vulnerable systems with NO user action and no host file required — making worms generally capable of spreading dramatically faster and more widely than a virus, since they don''t depend on a person unknowingly triggering them).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4139b0b4-93be-4418-b98b-a5ddaf038489', '3dc80833-8e27-452a-83a5-8c56dbb66ee9', 1, 'A worm is the malware requiring a host file and user action to spread, while a virus is the malware that spreads entirely on its own with no user action required — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b91ee518-e004-4335-8a28-34cef2fcb31f', '3dc80833-8e27-452a-83a5-8c56dbb66ee9', 2, 'Virus and worm are two different names for the exact same malware category, with no meaningful distinction in propagation mechanism between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0be05bc2-b760-4253-bed6-37efb689711d', '3dc80833-8e27-452a-83a5-8c56dbb66ee9', 3, 'Malware can never propagate across a network without some form of direct user action triggering each individual infection.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d123d11a-a6a4-4940-8e40-210d3700ec6b', '4d814d13-9a1c-4edd-9432-8475ab5385e6', 0, 'A Trojan horse (or Trojan) — malware disguised as, or bundled within, seemingly legitimate and desirable software, relying on the victim VOLUNTARILY installing it because it appears genuinely useful or wanted, rather than exploiting a technical vulnerability to force its way onto a system the way a worm does, or requiring the victim to merely open an already-infected file the way a virus does; the deception here is specifically about the software''s APPARENT PURPOSE and legitimacy, not about hiding within an already-trusted file.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a89007cb-e029-45d1-b629-d96291b42bfa', '4d814d13-9a1c-4edd-9432-8475ab5385e6', 1, 'A worm, since worms are specifically defined as malware disguised as legitimate, desirable software that a victim voluntarily chooses to install.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0251ae62-4f86-423f-87fc-203184a8ce0a', '4d814d13-9a1c-4edd-9432-8475ab5385e6', 2, 'A rootkit, since rootkits are specifically defined as malware disguised as legitimate software that a victim voluntarily downloads and installs believing it to be genuinely useful.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2a7bcd7d-1615-4220-b577-119bbfc54fca', '4d814d13-9a1c-4edd-9432-8475ab5385e6', 3, 'Malware disguised as legitimate, desirable software is not a real or meaningful attack pattern, since users would always recognize and avoid genuinely malicious software regardless of its apparent purpose.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('665f0898-41ca-4a28-9e57-b3f186155e4a', '2ae4c36d-115b-4b8b-bcae-85f74c74013d', 0, 'A race condition (specifically a Time-Of-Check to Time-Of-Use, or TOCTOU, vulnerability) — occurs when there is a meaningful time gap between when a system CHECKS a condition (like authorization) and when it actually ACTS on that check, and an attacker exploits that gap by changing the relevant state in between, so the action that ultimately executes no longer matches what was actually validated; the fix generally requires making the check-and-act sequence effectively ATOMIC (an indivisible, uninterruptible single operation) so no exploitable gap exists for an attacker to act within.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('58887a18-785c-47c8-b422-0658eb83cb87', '2ae4c36d-115b-4b8b-bcae-85f74c74013d', 1, 'A Trojan horse, since Trojan horses are specifically defined as exploiting a time gap between an authorization check and the actual action a system performs.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5d343f8-a57c-46ef-a6f1-1ada41b60d7f', '2ae4c36d-115b-4b8b-bcae-85f74c74013d', 2, 'Directory traversal, since directory traversal is specifically defined as exploiting the time gap between when a system checks authorization and when it actually performs the corresponding action.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b263eb0a-a141-48b3-a17f-48c84c6f0a95', '2ae4c36d-115b-4b8b-bcae-85f74c74013d', 3, 'A meaningful time gap between an authorization check and the corresponding action can never actually exist in real software, making this described vulnerability class a technical impossibility.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('15d14d73-f64b-4419-9670-f41024c809b9', '7086506d-8226-4919-8fd5-674926da0e1a', 0, 'An HID (Human Interface Device) attack / keystroke-injection attack — a small device (physically resembling an ordinary USB flash drive) is programmed to identify itself to the target computer as a KEYBOARD rather than storage media, and then automatically "types" a pre-programmed, malicious sequence of keystrokes the instant it''s plugged in; because operating systems generally trust HID keyboard input implicitly with no separate file-opening or execution step required, and typically don''t apply the same removable-media scrutiny they might to a device identifying as storage, this technique can execute malicious commands essentially instantly upon connection.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bd104e1a-f989-4b88-a54f-2809865289e3', '7086506d-8226-4919-8fd5-674926da0e1a', 1, 'Baiting, since baiting is specifically defined as a device that identifies itself as a keyboard and automatically types pre-programmed malicious commands the instant it''s plugged in.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('98ba24e2-b02b-47cb-a687-0f8df4c0e0c3', '7086506d-8226-4919-8fd5-674926da0e1a', 2, 'A logic bomb, since logic bombs are specifically defined as a physical USB device that identifies itself as a keyboard and immediately types a pre-programmed malicious keystroke sequence.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8f5beb45-c3c1-46a5-94fb-826c7a4235cb', '7086506d-8226-4919-8fd5-674926da0e1a', 3, 'A USB device can never be programmed to identify itself as a keyboard or automatically inject keystrokes; this described attack mechanism is not technically achievable.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89e1cdc4-549d-4509-9d42-833df88d11f1', '70eb0a83-22b4-407d-8126-7dc26ea620fa', 0, 'Function-level permission scoping (each individual function should have its own narrowly-scoped permissions specific to what IT needs, rather than one broad, shared permission set across every function — directly applying least privilege, covered in a prior paper, at a more granular level), securing the event sources that can actually TRIGGER a function (since an attacker who can inject or manipulate an event source can effectively trigger unauthorized function execution), and the greater difficulty of traditional host-based monitoring/EDR (covered in a prior paper) given functions'' genuinely ephemeral, short-lived execution — a real, distinct security profile shift from traditional server-based architecture, not simply an unchanged security posture handed off entirely to the provider.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b7ddae14-785b-48d7-8bac-2f72203c5fd2', '70eb0a83-22b4-407d-8126-7dc26ea620fa', 1, 'Serverless architecture eliminates every security consideration entirely, since the cloud provider''s full management of the underlying infrastructure means the customer bears absolutely no security responsibility of any kind.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d57e4ea7-b045-4c03-8043-8df8f6db0060', '70eb0a83-22b4-407d-8126-7dc26ea620fa', 2, 'Serverless functions should always share one single, broad permission set across every function in an application, since granular, function-specific permission scoping provides no meaningful security benefit.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff6e5ec0-5f65-4b76-a128-587acfd0925c', '70eb0a83-22b4-407d-8126-7dc26ea620fa', 3, 'Serverless architecture and traditional server-based architecture present functionally identical security considerations, with no meaningful difference in appropriate security practices between them.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('91872c90-9bc0-4a0e-bfc2-810a1c627095', '923aa232-4a51-4371-bb2c-cb6055747262', 0, 'A VM escape (or hypervisor escape) — malicious code running inside a guest VM breaks out of that VM''s isolation boundary and gains unauthorized access to the underlying HOST system or to OTHER VMs sharing the same physical hardware; this is considered particularly severe specifically because the entire premise of running multiple tenants'' workloads on shared physical hardware depends on the hypervisor''s isolation boundary genuinely holding — a successful VM escape potentially compromises every OTHER tenant sharing that same host, not just the originally-compromised VM, a fundamentally different and larger blast radius than a compromise contained within one VM.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5034b13a-e59d-402b-8817-6eb5d592520a', '923aa232-4a51-4371-bb2c-cb6055747262', 1, 'A container escape, since container escapes are specifically defined as malicious code breaking out of a hypervisor-managed virtual machine''s isolation boundary to access other VMs on the same host.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('89baf3c1-d735-4895-97d6-e8cab68ad28e', '923aa232-4a51-4371-bb2c-cb6055747262', 2, 'A race condition, since race conditions are specifically defined as malicious code breaking out of a VM''s hypervisor-enforced isolation boundary to access other tenants'' VMs on shared hardware.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f59ba9bd-c75e-40e5-94ae-0db9a42f3731', '923aa232-4a51-4371-bb2c-cb6055747262', 3, 'A hypervisor''s isolation between virtual machines running on the same physical host can never actually be broken or bypassed under any circumstance.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c50d47e3-0200-45ef-84f7-d138292d56ac', 'b348b9f3-6447-4e16-809c-079b44aa6d44', 0, 'A TPM (Trusted Platform Module) — a dedicated, tamper-resistant hardware chip (or an equivalent firmware-based implementation) built directly into a device, providing a genuine hardware root of trust specifically for securely generating and storing cryptographic keys (in a way that''s meaningfully harder to extract than keys stored purely in software) and supporting the secure/measured boot process (covered in a prior paper) by performing its cryptographic integrity-verification operations in dedicated hardware, rather than relying entirely on general-purpose software that could itself potentially be tampered with or compromised.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d7cb7c72-6905-4222-a8d3-31e1ff4df924', 'b348b9f3-6447-4e16-809c-079b44aa6d44', 1, 'A write blocker, since write blockers are specifically defined as a hardware-based root of trust for generating cryptographic keys and verifying boot process integrity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('814bd1b8-89be-456a-8b75-79412e838f4c', 'b348b9f3-6447-4e16-809c-079b44aa6d44', 2, 'A CASB, since CASBs are specifically defined as a dedicated, tamper-resistant hardware chip built into a device''s motherboard for cryptographic key generation and boot-process verification.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e0045eea-2ef2-40f1-862c-3857002018d5', 'b348b9f3-6447-4e16-809c-079b44aa6d44', 3, 'No dedicated hardware component exists for cryptographic key generation or boot-process integrity verification; these operations can only ever be performed in general-purpose software.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('69bdbabb-817e-4256-a159-e2b661752291', '80bd0fba-884f-4a2f-b051-34247fb2c036', 0, 'WPA3 provides meaningfully stronger protection against offline password-guessing attacks against the network''s pre-shared key (via a more robust handshake specifically resistant to the kind of offline dictionary/brute-force attack that a weaker WPA2 handshake was genuinely vulnerable to), and adds individualized data encryption for each connected client on open/public networks (meaningfully limiting one connected user''s ability to passively eavesdrop on another user''s traffic on the same open network, a real gap WPA2 (and especially fully open, unencrypted Wi-Fi) did not adequately address) — genuine, meaningful security improvements over WPA2, not merely a version-number change with no substantive difference.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a4109887-71de-4832-beff-1cd593beb974', '80bd0fba-884f-4a2f-b051-34247fb2c036', 1, 'WPA2 provides meaningfully stronger protection against offline password-guessing attacks and individualized per-client encryption on open networks than WPA3 does, making WPA2 the objectively more secure choice in every respect.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6dfa7d9f-762b-42c2-81b6-2457f9be03a5', '80bd0fba-884f-4a2f-b051-34247fb2c036', 2, 'WPA2 and WPA3 are functionally and cryptographically identical protocols under two different marketing names, with no meaningful security improvement in either direction.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44ff85b1-f655-486e-9b15-f28d556d3e31', '80bd0fba-884f-4a2f-b051-34247fb2c036', 3, 'Wireless network security protocols have no meaningful relationship to protecting against password-guessing attacks or eavesdropping between users on the same network.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('99b5caaf-a333-4c93-ade3-0eaa00db09be', '6c3bb75d-0d6c-49a1-bc27-99b670336011', 0, 'Emergency (or out-of-band) patching — a deliberately expedited patch deployment process, used specifically when a vulnerability''s severity and active-exploitation status genuinely justify bypassing (or significantly compressing) the normal testing cadence, accepting a real, explicitly acknowledged trade-off of somewhat higher regression risk (since normal testing time is compressed or skipped) in exchange for closing a genuinely severe, actively-exploited security gap faster; this should be a deliberate, exception-based process reserved for genuinely warranted situations, not the organization''s standard operating cadence for every routine patch.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('44c1402e-e6e1-462c-8ff7-4536df3df8c7', '6c3bb75d-0d6c-49a1-bc27-99b670336011', 1, 'The normal, standard two-week testing cadence should always be followed without exception in every situation, regardless of a vulnerability''s severity or active-exploitation status.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('db31b2c0-473d-48f3-a8c0-425625b739c1', '6c3bb75d-0d6c-49a1-bc27-99b670336011', 2, 'Emergency patching and the organization''s normal, routine patch testing cadence are the exact same process, with no meaningful distinction in urgency, testing rigor, or risk trade-off between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b647086-b338-43fb-864c-d449c229f6fc', '6c3bb75d-0d6c-49a1-bc27-99b670336011', 3, 'Patches can never realistically be deployed faster than an organization''s normal, standard testing cadence under any circumstance, regardless of a vulnerability''s actual severity.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('beb204c4-de65-4bf6-bd74-5d46ed455344', '9082b76d-453f-4117-acc9-c54689175eca', 0, 'Rules of Engagement (RoE) — a formal document, agreed upon by both parties BEFORE any actual penetration testing activity begins, precisely defining what systems/scope are authorized for testing (and explicitly what is OUT of scope, genuinely important since testing an out-of-scope system could itself constitute an unauthorized, potentially illegal intrusion), the testing timeframe, which specific techniques are and are not permitted, and emergency escalation/contact procedures — this document is what transforms penetration testing from what would otherwise be indistinguishable from an actual unauthorized attack into a genuinely authorized, legally protected engagement.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4d76dde-d299-4ac3-864b-275f49b23e7a', '9082b76d-453f-4117-acc9-c54689175eca', 1, 'A BAA, since BAAs are specifically defined as the formal, pre-engagement document establishing scope, timeframe, and authorized techniques for a penetration test.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c4388f1c-ee14-4fbc-adf4-f97cd8e69cdc', '9082b76d-453f-4117-acc9-c54689175eca', 2, 'A legal hold, since legal holds are specifically defined as the document establishing scope, timeframe, authorized techniques, and emergency contacts for a penetration test.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9df4fc6f-9411-46ba-b81a-26db0b47d171', '9082b76d-453f-4117-acc9-c54689175eca', 3, 'Penetration testing requires no formal, pre-agreed documentation of scope or authorized techniques; testers are always free to test whatever systems and use whatever techniques they judge appropriate.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e08b068c-f533-423e-96e8-ad3ec899ffe4', '29d2890c-e328-46e1-9c3a-709dd383f3d9', 0, 'Incident severity classification (often using defined tiers like P1/Critical through P4/Low, or similar naming) — categorizes each incident by its actual BUSINESS IMPACT and urgency (scope of systems affected, data sensitivity involved, business-function disruption, whether active exploitation is confirmed and ongoing), directly driving how much resourcing, escalation, and response speed a given incident receives; this is a genuinely different concept from CVSS (covered in a prior paper, which scores the TECHNICAL severity of a VULNERABILITY in the abstract) — the SAME underlying vulnerability or incident TYPE can warrant a dramatically different severity classification depending on the SPECIFIC business context it''s actually occurring in.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('944bdef6-e2bb-4cae-b180-d830faea3e1e', '29d2890c-e328-46e1-9c3a-709dd383f3d9', 1, 'CVSS, since CVSS is specifically defined as categorizing an incident''s severity by its business impact and urgency rather than scoring a vulnerability''s abstract technical severity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a96c044a-5f37-4306-a198-60ba74f98d5f', '29d2890c-e328-46e1-9c3a-709dd383f3d9', 2, 'MTTD and MTTR, since MTTD and MTTR are specifically defined as the framework for categorizing incidents by business impact and urgency, rather than measuring detection and response time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7c44e93c-126f-482c-a561-5cf6e4ae9375', '29d2890c-e328-46e1-9c3a-709dd383f3d9', 3, 'Every security incident, regardless of its actual scope, sensitivity, or business impact, always warrants the exact same level of urgency, resourcing, and response speed.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d36c5ff-2060-4660-bca0-f7e2467227ba', 'f12b1ac7-6533-49bb-bbd7-395027baaeb8', 0, 'SOC tiers (commonly Tier 1, Tier 2, and Tier 3 analysts) — Tier 1 analysts perform initial alert triage, handling straightforward, well-understood cases directly and escalating anything genuinely ambiguous or complex; Tier 2 analysts investigate those escalated cases more deeply, with greater experience and typically broader tool access; and Tier 3 analysts (often the most senior) handle the most sophisticated, novel threats and also frequently work on proactive threat hunting (covered in a prior paper) and improving/tuning detection capability itself, rather than purely reactive alert handling — this tiered structure lets a SOC efficiently allocate its most experienced (and most limited, expensive) analyst time to genuinely complex problems rather than every alert consuming senior-level attention regardless of actual complexity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7ab53d9d-fc21-442a-a250-b45f80a4dfa7', 'f12b1ac7-6533-49bb-bbd7-395027baaeb8', 1, 'A CSIRT, since CSIRT is specifically defined as the ongoing, tiered analyst structure (Tier 1/2/3) a SOC uses for routine, day-to-day alert triage and escalation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d3012015-ce96-49c6-a6e4-7cd38a63e0c0', 'f12b1ac7-6533-49bb-bbd7-395027baaeb8', 2, 'A RACI matrix, since RACI matrices are specifically defined as the tiered structure grouping SOC analysts into Tier 1, Tier 2, and Tier 3 experience levels.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff222868-bc05-4ee5-9b1c-91d4dde3abdb', 'f12b1ac7-6533-49bb-bbd7-395027baaeb8', 3, 'SOC analysts are never organized into any distinct tiers or experience levels; every analyst in a security operations center always handles every type of alert identically regardless of complexity.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4274bdec-d730-4949-bfd0-f508a2b79a2c', '0c768a81-3950-4ed1-9ce2-34308e8d011d', 0, 'Formal remediation SLA timelines (tied to CVSS severity, covered earlier this paper, and often further weighted by real-world exploitability and asset exposure, connecting to the vulnerability-management prioritization concept covered in a prior paper) create an ACCOUNTABLE, measurable, and consistently-enforced standard for how quickly different severity levels must actually be addressed — enabling the organization to track genuine compliance against a defined commitment, identify systemic remediation delays before they become a real problem, and ensure the highest-severity, most exploitable vulnerabilities on the most exposed systems genuinely get fixed fastest, rather than remediation priority being decided ad hoc, inconsistently, or based on whichever team happens to have available time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9678b308-994a-41e3-a85b-20a094320cf5', '0c768a81-3950-4ed1-9ce2-34308e8d011d', 1, 'Formal remediation timelines provide no meaningful organizational or security value, since remediating vulnerabilities in a genuinely ad hoc, inconsistent order based on convenience achieves an identical real-world security outcome.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('84cf033e-670a-453e-bd45-e9e3310c33d4', '0c768a81-3950-4ed1-9ce2-34308e8d011d', 2, 'A gap analysis, since gap analyses are specifically defined as formal, severity-tiered vulnerability remediation timelines like 48 hours for critical and 30 days for medium severity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('01f26b8b-b396-4f37-9ca5-7e88bd3dd3c0', '0c768a81-3950-4ed1-9ce2-34308e8d011d', 3, 'Every vulnerability, regardless of its actual CVSS severity or real-world exploitability, should always be remediated within the exact same fixed timeframe with no differentiation by severity.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6ec8b41d-084b-4e91-9331-f576373d6cbc', '0fea3249-3e55-4e59-9d69-a5ced3784af6', 0, 'Static analysis (examining a file''s code, structure, embedded strings, and other characteristics WITHOUT ever actually executing it — genuinely safer in one specific sense, since the file''s malicious payload never actually runs during this examination, but can be defeated by malware specifically designed to resist static inspection, like heavily obfuscated or packed code) and dynamic analysis (actually EXECUTING the file, typically inside an isolated sandbox environment, covered in a prior paper, to directly observe its real runtime behavior — file/registry changes, network connections attempted — catching genuinely evasive malware that behaves differently or reveals its true nature only once actually run, at the cost of the real supervision and isolation rigor sandboxing requires to safely allow that execution).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e206a921-b6b9-4040-9b9a-2ba4609b7249', '0fea3249-3e55-4e59-9d69-a5ced3784af6', 1, 'Dynamic analysis is examining a file''s code without executing it, while static analysis is actually running the file inside a sandbox to observe its behavior — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b8f50f0-51eb-467e-84c9-8e9a1376443a', '0fea3249-3e55-4e59-9d69-a5ced3784af6', 2, 'Static and dynamic malware analysis are two different names for the exact same analytical approach, with no meaningful distinction in whether the file is actually executed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5114ec68-6235-474f-b4c9-7d9d98cb262b', '0fea3249-3e55-4e59-9d69-a5ced3784af6', 3, 'A suspicious file''s actual behavior and characteristics can never be meaningfully analyzed through any technique without directly infecting a real, unprotected production system.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0d5147b4-380f-4d1d-a00c-caacf9065574', '750645e7-2216-438b-98c0-9d4a9c4bdadb', 0, 'First-party coverage (protecting the INSURED company''s own direct losses and costs — forensic investigation, recovery, business interruption, its own legal defense costs) and third-party coverage (protecting against LIABILITY claims from OTHER parties — customers, partners, regulators — harmed by the breach and seeking compensation from the company); this directly refines the general cyber insurance concept (covered generally in a prior paper) with the important distinction that these are genuinely separate coverage categories, and a policy covering one does not automatically cover the other — an organization needs to deliberately evaluate whether its coverage genuinely addresses both realistic exposure categories.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0bc8a457-fe59-4647-acd5-a735c37b4dea', '750645e7-2216-438b-98c0-9d4a9c4bdadb', 1, 'Third-party coverage is specifically defined as protecting the insured company''s own direct losses, while first-party coverage protects against liability claims from other parties — the reverse of the correct definitions.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7de40d35-65a3-4c02-8486-4c012c0bbee0', '750645e7-2216-438b-98c0-9d4a9c4bdadb', 2, 'First-party and third-party cyber insurance coverage are two different names for the exact same coverage category, with no meaningful distinction between them.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb98d662-8cfc-49dd-9b6d-f26069ab65f6', '750645e7-2216-438b-98c0-9d4a9c4bdadb', 3, 'Cyber insurance policies can only ever cover a company''s own direct losses; coverage for liability claims brought by other, external parties does not exist as a real insurance category.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6cc5719f-f35d-4c99-afba-c447e8dfede6', 'aa453cf2-8e51-4f86-a7e5-c6d90f559e02', 0, 'A right-to-audit clause — a specific contractual provision giving the customer the EXPLICIT, LEGALLY ENFORCEABLE right to conduct (or commission) its own independent security audit of the vendor, rather than depending entirely on whatever information the vendor voluntarily chooses to share; this genuinely strengthens vendor risk management (covered in a prior paper) beyond passive reliance on vendor-provided attestations, since a vendor motivated to look good on paper might otherwise selectively share only favorable information, and this clause gives the customer real, independent verification power specifically written into the contract itself.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e4194124-917b-4187-bfa4-b891949e7575', 'aa453cf2-8e51-4f86-a7e5-c6d90f559e02', 1, 'A BAA, since BAAs are specifically defined as the general contractual clause giving a customer the right to independently audit any vendor''s security practices.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9de098b9-c87e-4fef-bb3f-31185ec57659', 'aa453cf2-8e51-4f86-a7e5-c6d90f559e02', 2, 'An MOU, since MOUs are specifically defined as the legally enforceable clause granting a customer the explicit contractual right to conduct an independent vendor security audit.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bb077c89-8cad-47f6-9127-f7041fcab8ea', 'aa453cf2-8e51-4f86-a7e5-c6d90f559e02', 3, 'A company can never contractually secure the right to independently audit a vendor''s security practices; verification must always rely entirely on whatever the vendor voluntarily chooses to share.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5b75e9d7-ca11-4e81-a15d-87081dec6981', '7afda359-fbc0-438f-b532-124e590bee9c', 0, 'SOX (the Sarbanes-Oxley Act) — a US federal law specifically requiring publicly traded companies to maintain strong, verifiable internal controls over financial reporting (including the IT systems and security controls protecting financial data''s integrity and accuracy), enacted specifically in response to major historical corporate accounting scandals that undermined public trust in published financial statements — genuinely distinct in scope and focus from HIPAA (covered in a prior paper, health information), GDPR (covered in a prior paper, EU personal data broadly), and PCI-DSS (covered in a prior paper, an industry standard for payment card data, not a government law) — SOX specifically targets the integrity of FINANCIAL REPORTING for publicly traded companies.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f6012ea-3a6d-47ba-b2d0-539bdf03d991', '7afda359-fbc0-438f-b532-124e590bee9c', 1, 'PCI-DSS, since PCI-DSS is specifically the US federal law requiring publicly traded companies to maintain internal controls over financial reporting integrity.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('55d9ba83-035b-4ae1-b014-38e181c3a7de', '7afda359-fbc0-438f-b532-124e590bee9c', 2, 'HIPAA, since HIPAA is specifically the law enacted in response to corporate accounting scandals, requiring internal controls over publicly traded companies'' financial reporting.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0ec66996-c7b8-410c-9c7c-db56ff60da00', '7afda359-fbc0-438f-b532-124e590bee9c', 3, 'No US federal law imposes any requirement on publicly traded companies regarding internal controls over the accuracy or integrity of their financial reporting or related IT systems.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d6b9f39-badd-4447-a5c8-6ebf5862793a', '237e1348-57d3-4580-9c43-ec900ea533e6', 0, 'Asset management (specifically covering the full asset lifecycle from acquisition through active use to secure disposal) — maintains a genuine, accurate inventory of every IT asset throughout its entire lifecycle, and critically includes secure data sanitization/destruction procedures BEFORE a device is disposed of, resold, or repurposed, since simply deleting files or performing a standard format does NOT reliably prevent forensic data recovery from the underlying storage media — proper sanitization (cryptographic erasure, physical destruction, or verified secure-wipe procedures, depending on the asset''s sensitivity and reuse plans) is what actually closes this real, practical, and often-overlooked data-exposure risk.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('f08f22d9-beb8-4331-be03-881a13809229', '237e1348-57d3-4580-9c43-ec900ea533e6', 1, 'Data classification, since data classification is specifically defined as the end-to-end process governing a physical IT asset from acquisition through active use to secure disposal.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83d19bbc-5858-45dc-880b-25067ceac689', '237e1348-57d3-4580-9c43-ec900ea533e6', 2, 'Onboarding, since onboarding is specifically defined as the governance process covering an IT asset''s full lifecycle from acquisition through secure disposal, rather than an employee''s pre-employment vetting.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d703e4a-8942-45d8-a6a4-3c6eb713bf47', '237e1348-57d3-4580-9c43-ec900ea533e6', 3, 'Simply deleting files or performing a standard disk format before disposing of a device is always fully sufficient to prevent any possibility of the previously-stored data being recovered.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
